:root {
  color-scheme: dark;
  --ink: #090b0a;
  --panel: #0d100e;
  --panel-raised: #111512;
  --line: #2b322d;
  --muted: #858c85;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
  --cyan: #91f3a8;
  --grid-line: rgba(32, 239, 79, .025);
  --orb-core: #010602;
  --orb-glow: #20ef4f;
  --mono: "DM Mono", "Courier New", monospace;
  --display: "Space Grotesk", "Trebuchet MS", sans-serif;
  font-family: var(--mono);
  background: var(--ink);
  color: var(--paper);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 32px; }
body {
  min-width: 320px;
  margin: 0;
  background-color: var(--ink);
  background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  color: var(--paper);
}
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--green); outline-offset: 4px; }
.is-option-selected:focus-visible { outline: 0; }
.page-shell { width: min(1120px, calc(100% - 64px)); margin: 0 auto; }
.topbar { min-height: 76px; display: flex; align-items: center; gap: 30px; border-bottom: 1px solid var(--line); }
.wordmark { display: inline-flex; align-items: center; gap: 10px; color: var(--paper); font: 600 13px var(--mono); letter-spacing: 0; white-space: nowrap; }
.wordmark-mark { color: var(--green); font: 700 19px var(--display); }
.wordmark-mark span { color: var(--paper); }
.wordmark-muted { color: var(--muted); }
.system-status { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 10px; }
.status-light { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px rgba(157, 242, 173, .7); }
.site-nav { display: flex; gap: 25px; margin-left: auto; }
.site-nav a { color: #bdc3bc; font-size: 11px; transition: color .2s ease; }
.site-nav a:hover { color: var(--green); }
.site-nav a span { margin-left: 4px; color: var(--green-dim); font-size: 9px; }
.menu-toggle { display: none; }
.terminal-frame { border: 1px solid var(--line); background: rgba(9, 11, 10, .92); }
.hero { position: relative; margin-top: 28px; padding: 20px 30px 0; overflow: hidden; }
.hero::before { position: absolute; top: 0; left: 0; width: 3px; height: 88px; background: var(--green); content: ""; }
.hero-topline { display: flex; flex-wrap: wrap; gap: 8px 26px; color: var(--muted); font-size: 11px; }
.hero-topline span:first-child { color: var(--green); }
.hero-main { display: grid; grid-template-columns: minmax(0, 1fr) 220px; gap: 32px; align-items: center; padding: 64px 0 52px; }
.eyebrow { margin: 0 0 18px; color: var(--muted); font-size: 11px; letter-spacing: .08em; }
.eyebrow span { color: var(--green-dim); }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 12px; font: 500 clamp(54px, 8vw, 98px)/.94 var(--display); letter-spacing: 0; }
.name-cursor { color: var(--green); }
.title-period { color: var(--green); }
.hero-role { margin: 20px 0 16px; color: var(--green); font-size: 15px; }
.hero-role span { color: var(--muted); }
.hero-rule { height: 1px; width: min(100%, 540px); background: var(--line); }
.intro { max-width: 570px; margin: 23px 0 20px; color: #bbc1ba; font-size: 16px; line-height: 1.8; }
.prompt-mark { margin-right: 7px; color: var(--green); }
.text-link { display: inline-flex; gap: 14px; align-items: center; padding: 11px 0; color: var(--green); font-size: 12px; letter-spacing: .03em; }
.text-link span { font-size: 16px; transition: transform .2s ease; }
.text-link:hover span { transform: translate(3px, 3px); }
.hero-aside { align-self: stretch; display: flex; flex-direction: column; justify-content: flex-end; border-left: 1px solid var(--line); padding-left: 22px; }
.orbit-mark { width: 105px; height: 105px; display: grid; place-items: center; align-self: flex-end; margin: 0 4px auto 0; border: 1px solid var(--line); border-radius: 50%; color: var(--green); font: 500 50px var(--display); position: relative; }
.orbit-mark::before, .orbit-mark::after { position: absolute; content: ""; border: 1px solid var(--green-dim); border-radius: 50%; }
.orbit-mark::before { inset: 10px; }
.orbit-mark::after { width: 7px; height: 7px; top: 10px; right: 12px; background: var(--green); }
.orbit-mark i { position: absolute; right: 5px; bottom: 14px; width: 5px; height: 5px; background: var(--cyan); }
.readout-label, .aside-coordinate span:first-child { color: var(--muted); font-size: 11px; }
.aside-readout strong { display: block; margin-top: 10px; font: 500 20px/1.35 var(--display); }
.green-dot { color: var(--green); }
.aside-coordinate { display: flex; flex-direction: column; gap: 5px; margin-top: 22px; padding-top: 11px; border-top: 1px solid var(--line); }
.aside-coordinate span:last-child { color: var(--cyan); font-size: 12px; }
.hero-bottomline { min-height: 49px; display: flex; align-items: center; flex-wrap: wrap; gap: 10px 28px; border-top: 1px solid var(--line); color: var(--muted); font-size: 11px; }
.hero-bottomline strong { color: var(--green); font-weight: 400; }
.hero-bottomline a { margin-left: auto; color: var(--green); font-size: 20px; }
.index-section { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); margin: 12px 0 110px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.index-tile { min-height: 108px; display: grid; grid-template-columns: 1fr auto; align-content: center; gap: 7px 12px; padding: 16px 19px; border-right: 1px solid var(--line); transition: background .2s ease; }
.index-tile:first-child { border-left: 1px solid var(--line); }
.index-tile:hover { background: rgba(157, 242, 173, .06); }
.tile-number { color: var(--green-dim); font-size: 11px; }
.tile-title { grid-column: 1 / -1; color: var(--green); font: 600 18px var(--display); }
.tile-detail { color: #aeb5ad; font-size: 12px; }
.tile-detail i { color: var(--green); font-style: normal; }
.content-section { padding: 0 0 90px; scroll-margin-top: 32px; }
.section-heading { margin-bottom: 29px; }
.section-heading .eyebrow { margin-bottom: 10px; }
h2 { margin-bottom: 8px; font: 500 clamp(32px, 5vw, 48px)/1.12 var(--display); }
h2 span { color: var(--green); }
.section-note { margin: 10px 0 0; color: var(--muted); font-size: 13px; }
.project-list { border-top: 1px solid var(--line); }
.project-row { display: grid; grid-template-columns: 44px minmax(0, 1fr) 175px 26px; gap: 17px; align-items: center; min-height: 112px; border-bottom: 1px solid var(--line); transition: background .2s ease; cursor: pointer; padding: 0 8px; }
.project-row:hover { background: rgba(32, 239, 79, .04); }
.project-index { align-self: start; padding-top: 27px; color: var(--green-dim); font-size: 12px; }
.project-copy h3 { margin: 0 0 7px; font: 500 18px var(--display); }
.project-copy p { max-width: 610px; margin: 0; color: var(--muted); font-size: 13px; line-height: 1.7; }
.project-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.project-tags span { padding: 6px 8px; border: 1px solid var(--line); color: var(--cyan); font-size: 10px; }
.project-arrow { color: var(--green); font-size: 19px; transition: transform .2s ease; }
.project-row:hover .project-arrow { transform: translate(3px, -3px); }
.skills-section { padding: 28px 0 82px; border-top: 1px solid var(--line); }
.skills-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.skill-group { min-height: 142px; padding: 18px 20px; border-right: 1px solid var(--line); }
.skill-group:first-child { border-left: 1px solid var(--line); }
.skill-number { color: var(--green-dim); font-size: 11px; }
.skill-group h3 { margin: 22px 0 10px; color: var(--paper); font: 500 13px var(--mono); }
.skill-group p { margin: 0; color: #adb4ac; font-size: 12px; line-height: 1.8; }
.skill-group p span { color: var(--green); }
.about-contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 50px; padding-top: 10px; border-top: 1px solid var(--line); }
.about-contact-grid .content-section { padding-bottom: 76px; }
.about-copy, .contact-copy { max-width: 490px; color: #b6bdb6; font-size: 13px; line-height: 1.9; }
.about-copy strong { color: var(--green); font-weight: 400; }
.about-meta { display: flex; flex-direction: column; gap: 7px; margin-top: 26px; padding-top: 12px; border-top: 1px solid var(--line); font-size: 9px; }
.about-meta span { color: var(--muted); }
.about-meta strong { color: var(--cyan); font-weight: 400; }
.contact-link { display: inline-flex; align-items: center; gap: 20px; margin-top: 10px; padding: 14px 0; border-bottom: 1px solid var(--green-dim); color: var(--green); font-size: 13px; }
.contact-link span { font-size: 17px; }
.contact-hint { margin-top: 12px; color: var(--muted); font-size: 10px; }
.footer { min-height: 70px; display: flex; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid var(--line); color: var(--muted); font-size: 9px; }
.footer > a:last-child { color: var(--green); }
.footer-mark { font-size: 10px; }
.command-dock { position: fixed; right: max(20px, calc((100vw - 1120px) / 2)); bottom: 18px; z-index: 5; width: min(360px, calc(100vw - 32px)); min-height: 44px; display: flex; align-items: center; gap: 10px; padding: 0 13px; border: 1px solid #405446; background: #101612; box-shadow: 0 6px 28px rgba(0, 0, 0, .38); }
.dock-prompt { color: var(--green); font-size: 12px; }
.command-dock input { min-width: 0; flex: 1; height: 42px; border: 0; outline: 0; background: transparent; color: var(--paper); font-size: 10px; }
.command-dock input::placeholder { color: var(--muted); }
.dock-hint { color: var(--green-dim); font-size: 8px; white-space: nowrap; }
.command-output { position: absolute; right: 0; bottom: 52px; display: none; width: 100%; margin: 0; padding: 12px; border: 1px solid var(--line); background: var(--panel); color: var(--green); font-size: 10px; line-height: 1.7; }
.command-output.is-visible { display: block; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 760px) {
  .page-shell { width: min(100% - 34px, 600px); }
  .topbar { min-height: 66px; gap: 13px; }
  .system-status { margin-left: auto; font-size: 8px; }
  .menu-toggle { width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--line); background: var(--panel); color: var(--green); cursor: pointer; }
  .menu-icon { font-size: 20px; line-height: 1; transition: transform .2s ease; }
