  .home-screen .hero-topline { margin-bottom: 20px; }
  .home-screen h1 { font-size: clamp(48px, 11vw, 68px); }
  .home-screen .intro { margin-bottom: 0; }
  .home-directory { width: 100%; }
  .menu-item.folder-tile { min-height: 86px; padding: 9px; }
  .directory-hint { margin-top: 10px; }
  .page-controls { gap: 12px; }
  .keyboard-hint { gap: 4px; font-size: 7px; }
  .keyboard-hint kbd { min-width: 17px; }
  .keyboard-hint .hint-divider { display: none; }
}
@media (max-width: 460px) {
  .route-bar { gap: 6px; font-size: 8px; }
  .home-screen.is-active { gap: 17px; }
  .home-screen .hero-topline { gap: 6px 10px; margin-bottom: 16px; font-size: 6px; }
  .home-screen h1 { font-size: clamp(43px, 11vw, 54px); }
  .menu-item { min-height: 39px; padding: 0 8px; font-size: 9px; }
  .page-controls { gap: 8px; }
  .keyboard-hint { gap: 3px; flex: 1; justify-content: flex-start; font-size: 6px; white-space: nowrap; }
  .keyboard-hint .hint-divider { display: none; }
}
@media (max-height: 700px) {
  .home-screen.is-active { gap: 12px; padding: 12px 14px; }
  .home-screen .hero-topline { margin-bottom: 8px; }
  .home-screen .eyebrow { margin-bottom: 6px; }
  .home-screen h1 { font-size: clamp(38px, 6vh, 52px); }
  .home-screen .hero-role { margin: 7px 0; }
  .home-screen .intro { margin: 8px 0 0; font-size: 9px; line-height: 1.35; }
  .menu-item.folder-tile { min-height: 60px; grid-template-columns: 23px minmax(0, 1fr) 14px; gap: 3px 6px; padding: 6px; }
  .menu-item.folder-tile .folder-icon { width: 19px; height: 13px; }
  .menu-item.folder-tile .folder-icon::before { top: -4px; width: 7px; height: 3px; }
  .folder-name { font-size: 9px; }
  .folder-meta { font-size: 6px; }
  .directory-heading { min-height: 24px; }
  .directory-hint { margin-top: 3px; font-size: 7px; }
}
@media (max-height: 560px) {
  .page-shell { min-height: 0; }
  .topbar { min-height: 68px; padding-top: 6px; padding-bottom: 3px; }
  .route-bar { order: 0; width: auto; margin: 0 0 0 auto; font-size: 7px; }
  .system-status { font-size: 7px; }
  .page-controls { min-height: 42px; }
  .home-screen.is-active { gap: 8px; }
  .menu-item.folder-tile { min-height: 50px; }
  .directory-heading { min-height: 21px; }
  .directory-hint { margin-top: 1px; }
}
@media (min-width: 761px) and (max-height: 760px) {
  #screen-about { padding-block: 24px; }
}
@media (min-width: 1300px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 48px; }
  .home-content { max-width: 1100px; }
  .intro { max-width: 880px; }
  .hero-rule, .home-menu { width: min(100%, 880px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
  .skills-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}
@media (min-width: 1700px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 64px; }
  .home-content { max-width: 1300px; }
  .intro { max-width: 1020px; }
  .hero-rule, .home-menu { width: min(100%, 1020px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}

before.content:
:root {
  color-scheme: dark;
  --ink: #090b0a;
  --panel: #0d100e;
  --panel-raised: #111512;
  --line: #2b322d;
  --muted: #858c85;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
  --cyan: #91f3a8;
  --grid-line: rgba(32, 239, 79, .025);
  --orb-core: #010602;
  --orb-glow: #20ef4f;
  --mono: "DM Mono", "Courier New", monospace;
  --display: "Space Grotesk", "Trebuchet MS", sans-serif;
  font-family: var(--mono);
  background: var(--ink);
  color: var(--paper);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 32px; }
body {
  min-width: 320px;
  margin: 0;
  background-color: var(--ink);
  background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  color: var(--paper);
}
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--green); outline-offset: 4px; }
.is-option-selected:focus-visible { outline: 0; }
.page-shell { width: min(1120px, calc(100% - 64px)); margin: 0 auto; }
.topbar { min-height: 76px; display: flex; align-items: center; gap: 30px; border-bottom: 1px solid var(--line); }
.wordmark { display: inline-flex; align-items: center; gap: 10px; color: var(--paper); font: 600 13px var(--mono); letter-spacing: 0; white-space: nowrap; }
.wordmark-mark { color: var(--green); font: 700 19px var(--display); }
.wordmark-mark span { color: var(--paper); }
.wordmark-muted { color: var(--muted); }
.system-status { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 10px; }
.status-light { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px rgba(157, 242, 173, .7); }
.site-nav { display: flex; gap: 25px; margin-left: auto; }
.site-nav a { color: #bdc3bc; font-size: 11px; transition: color .2s ease; }
.site-nav a:hover { color: var(--green); }
.site-nav a span { margin-left: 4px; color: var(--green-dim); font-size: 9px; }
.menu-toggle { display: none; }
.terminal-frame { border: 1px solid var(--line); background: rgba(9, 11, 10, .92); }
.hero { position: relative; margin-top: 28px; padding: 20px 30px 0; overflow: hidden; }
.hero::before { position: absolute; top: 0; left: 0; width: 3px; height: 88px; background: var(--green); content: ""; }
.hero-topline { display: flex; flex-wrap: wrap; gap: 8px 26px; color: var(--muted); font-size: 11px; }
.hero-topline span:first-child { color: var(--green); }
.hero-main { display: grid; grid-template-columns: minmax(0, 1fr) 220px; gap: 32px; align-items: center; padding: 64px 0 52px; }
.eyebrow { margin: 0 0 18px; color: var(--muted); font-size: 11px; letter-spacing: .08em; }
.eyebrow span { color: var(--green-dim); }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 12px; font: 500 clamp(54px, 8vw, 98px)/.94 var(--display); letter-spacing: 0; }
.name-cursor { color: var(--green); }
.title-period { color: var(--green); }
.hero-role { margin: 20px 0 16px; color: var(--green); font-size: 15px; }
.hero-role span { color: var(--muted); }
.hero-rule { height: 1px; width: min(100%, 540px); background: var(--line); }
.intro { max-width: 570px; margin: 23px 0 20px; color: #bbc1ba; font-size: 16px; line-height: 1.8; }
.prompt-mark { margin-right: 7px; color: var(--green); }
.text-link { display: inline-flex; gap: 14px; align-items: center; padding: 11px 0; color: var(--green); font-size: 12px; letter-spacing: .03em; }
.text-link span { font-size: 16px; transition: transform .2s ease; }
.text-link:hover span { transform: translate(3px, 3px); }
.hero-aside { align-self: stretch; display: flex; flex-direction: column; justify-content: flex-end; border-left: 1px solid var(--line); padding-left: 22px; }
.orbit-mark { width: 105px; height: 105px; display: grid; place-items: center; align-self: flex-end; margin: 0 4px auto 0; border: 1px solid var(--line); border-radius: 50%; color: var(--green); font: 500 50px var(--display); position: relative; }
.orbit-mark::before, .orbit-mark::after { position: absolute; content: ""; border: 1px solid var(--green-dim); border-radius: 50%; }
.orbit-mark::before { inset: 10px; }
.orbit-mark::after { width: 7px; height: 7px; top: 10px; right: 12px; background: var(--green); }
.orbit-mark i { position: absolute; right: 5px; bottom: 14px; width: 5px; height: 5px; background: var(--cyan); }
.readout-label, .aside-coordinate span:first-child { color: var(--muted); font-size: 11px; }
.aside-readout strong { display: block; margin-top: 10px; font: 500 20px/1.35 var(--display); }
.green-dot { color: var(--green); }
.aside-coordinate { display: flex; flex-direction: column; gap: 5px; margin-top: 22px; padding-top: 11px; border-top: 1px solid var(--line); }
.aside-coordinate span:last-child { color: var(--cyan); font-size: 12px; }
.hero-bottomline { min-height: 49px; display: flex; align-items: center; flex-wrap: wrap; gap: 10px 28px; border-top: 1px solid var(--line); color: var(--muted); font-size: 11px; }
.hero-bottomline strong { color: var(--green); font-weight: 400; }
.hero-bottomline a { margin-left: auto; color: var(--green); font-size: 20px; }
.index-section { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); margin: 12px 0 110px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.index-tile { min-height: 108px; display: grid; grid-template-columns: 1fr auto; align-content: center; gap: 7px 12px; padding: 16px 19px; border-right: 1px solid var(--line); transition: background .2s ease; }
.index-tile:first-child { border-left: 1px solid var(--line); }
.index-tile:hover { background: rgba(157, 242, 173, .06); }
.tile-number { color: var(--green-dim); font-size: 11px; }
.tile-title { grid-column: 1 / -1; color: var(--green); font: 600 18px var(--display); }
.tile-detail { color: #aeb5ad; font-size: 12px; }
.tile-detail i { color: var(--green); font-style: normal; }
.content-section { padding: 0 0 90px; scroll-margin-top: 32px; }
.section-heading { margin-bottom: 29px; }
.section-heading .eyebrow { margin-bottom: 10px; }
h2 { margin-bottom: 8px; font: 500 clamp(32px, 5vw, 48px)/1.12 var(--display); }
h2 span { color: var(--green); }
.section-note { margin: 10px 0 0; color: var(--muted); font-size: 13px; }
.project-list { border-top: 1px solid var(--line); }
.project-row { display: grid; grid-template-columns: 44px minmax(0, 1fr) 175px 26px; gap: 17px; align-items: center; min-height: 112px; border-bottom: 1px solid var(--line); transition: background .2s ease; cursor: pointer; padding: 0 8px; }
.project-row:hover { background: rgba(32, 239, 79, .04); }
.project-index { align-self: start; padding-top: 27px; color: var(--green-dim); font-size: 12px; }
.project-copy h3 { margin: 0 0 7px; font: 500 18px var(--display); }
.project-copy p { max-width: 610px; margin: 0; color: var(--muted); font-size: 13px; line-height: 1.7; }
.project-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.project-tags span { padding: 6px 8px; border: 1px solid var(--line); color: var(--cyan); font-size: 10px; }
.project-arrow { color: var(--green); font-size: 19px; transition: transform .2s ease; }
.project-row:hover .project-arrow { transform: translate(3px, -3px); }
.skills-section { padding: 28px 0 82px; border-top: 1px solid var(--line); }
.skills-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.skill-group { min-height: 142px; padding: 18px 20px; border-right: 1px solid var(--line); }
.skill-group:first-child { border-left: 1px solid var(--line); }
.skill-number { color: var(--green-dim); font-size: 11px; }
.skill-group h3 { margin: 22px 0 10px; color: var(--paper); font: 500 13px var(--mono); }
.skill-group p { margin: 0; color: #adb4ac; font-size: 12px; line-height: 1.8; }
.skill-group p span { color: var(--green); }
.about-contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 50px; padding-top: 10px; border-top: 1px solid var(--line); }
.about-contact-grid .content-section { padding-bottom: 76px; }
.about-copy, .contact-copy { max-width: 490px; color: #b6bdb6; font-size: 13px; line-height: 1.9; }
.about-copy strong { color: var(--green); font-weight: 400; }
.about-meta { display: flex; flex-direction: column; gap: 7px; margin-top: 26px; padding-top: 12px; border-top: 1px solid var(--line); font-size: 9px; }
.about-meta span { color: var(--muted); }
.about-meta strong { color: var(--cyan); font-weight: 400; }
.contact-link { display: inline-flex; align-items: center; gap: 20px; margin-top: 10px; padding: 14px 0; border-bottom: 1px solid var(--green-dim); color: var(--green); font-size: 13px; }
.contact-link span { font-size: 17px; }
.contact-hint { margin-top: 12px; color: var(--muted); font-size: 10px; }
.footer { min-height: 70px; display: flex; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid var(--line); color: var(--muted); font-size: 9px; }
.footer > a:last-child { color: var(--green); }
.footer-mark { font-size: 10px; }
.command-dock { position: fixed; right: max(20px, calc((100vw - 1120px) / 2)); bottom: 18px; z-index: 5; width: min(360px, calc(100vw - 32px)); min-height: 44px; display: flex; align-items: center; gap: 10px; padding: 0 13px; border: 1px solid #405446; background: #101612; box-shadow: 0 6px 28px rgba(0, 0, 0, .38); }
.dock-prompt { color: var(--green); font-size: 12px; }
.command-dock input { min-width: 0; flex: 1; height: 42px; border: 0; outline: 0; background: transparent; color: var(--paper); font-size: 10px; }
.command-dock input::placeholder { color: var(--muted); }
.dock-hint { color: var(--green-dim); font-size: 8px; white-space: nowrap; }
.command-output { position: absolute; right: 0; bottom: 52px; display: none; width: 100%; margin: 0; padding: 12px; border: 1px solid var(--line); background: var(--panel); color: var(--green); font-size: 10px; line-height: 1.7; }
.command-output.is-visible { display: block; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 760px) {
  .page-shell { width: min(100% - 34px, 600px); }
  .topbar { min-height: 66px; gap: 13px; }
  .system-status { margin-left: auto; font-size: 8px; }
  .menu-toggle { width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--line); background: var(--panel); color: var(--green); cursor: pointer; }
  .menu-icon { font-size: 20px; line-height: 1; transition: transform .2s ease; }
  .menu-toggle[aria-expanded="true"] .menu-icon { transform: rotate(45deg); }
  .site-nav { position: absolute; top: 58px; right: 17px; z-index: 4; display: none; width: min(230px, calc(100vw - 34px)); flex-direction: column; gap: 0; border: 1px solid var(--line); background: var(--panel); }
  .site-nav.is-open { display: flex; }
  .site-nav a { padding: 14px; border-bottom: 1px solid var(--line); }
  .site-nav a:last-child { border-bottom: 0; }
  .hero { margin-top: 18px; padding: 16px 17px 0; }
  .hero-topline { gap: 7px 13px; font-size: 8px; }
  .hero-main { grid-template-columns: minmax(0, 1fr) 112px; gap: 12px; padding: 50px 0 30px; }
  .eyebrow { font-size: 8px; }
  h1 { font-size: clamp(42px, 10vw, 66px); }
  .hero-role { margin: 14px 0; font-size: 11px; }
  .intro { font-size: 12px; line-height: 1.8; }
  .hero-aside { padding-left: 12px; }
  .orbit-mark { width: 70px; height: 70px; font-size: 34px; }
  .aside-readout strong { font-size: 14px; }
  .aside-coordinate span:last-child { font-size: 8px; }
  .hero-bottomline { gap: 9px 15px; padding: 10px 0; font-size: 8px; }
  .hero-bottomline a { font-size: 17px; }
  .index-section { grid-template-columns: repeat(2, 1fr); margin-bottom: 80px; }
  .index-tile { min-height: 94px; padding: 13px; border-bottom: 1px solid var(--line); }
  .index-tile:nth-child(2) { border-right: 1px solid var(--line); }
  .index-tile:nth-child(3) { border-left: 1px solid var(--line); border-bottom: 0; }
  .index-tile:nth-child(4) { border-bottom: 0; }
  .tile-title { font-size: 16px; }
  .tile-detail { font-size: 9px; }
  .content-section { padding-bottom: 66px; }
  .project-row { grid-template-columns: 28px minmax(0, 1fr) 22px; gap: 10px; padding: 17px 0; }
  .project-index { padding-top: 2px; }
  .project-copy h3 { font-size: 15px; }
  .project-copy p { font-size: 10px; }
  .project-tags { grid-column: 2; grid-row: 2; }
  .project-arrow { grid-column: 3; grid-row: 1; }
  .skills-grid { grid-template-columns: 1fr; }
  .skill-group { min-height: auto; padding: 15px; border-right: 0; border-bottom: 1px solid var(--line); }
  .skill-group:first-child { border-left: 1px solid var(--line); }
  .skill-group:last-child { border-bottom: 0; }
  .skill-group h3 { margin: 12px 0 6px; }
  .about-contact-grid { grid-template-columns: 1fr; gap: 0; }
  .about-contact-grid .content-section { padding-bottom: 54px; }
  .footer { min-height: 62px; flex-wrap: wrap; padding: 12px 0 58px; font-size: 8px; }
  .footer > span { order: 3; width: 100%; }
  .command-dock { right: 12px; bottom: 10px; width: calc(100vw - 24px); }
}
@media (max-width: 390px) {
  .page-shell { width: calc(100% - 24px); }
  .hero { padding-right: 12px; padding-left: 12px; }
  .hero-topline { font-size: 7px; }
  .hero-main { grid-template-columns: minmax(0, 1fr) 94px; gap: 9px; }
  h1 { font-size: 39px; }
  .orbit-mark { width: 60px; height: 60px; }
  .aside-readout strong { font-size: 12px; }
  .aside-coordinate span:last-child { font-size: 7px; }
  .hero-bottomline { gap: 8px 10px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; }
}
body {
  height: 100vh;
  min-height: 100vh;
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--ink);
  background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  color: var(--paper);
}
html, body { min-height: 100vh; }
.page-shell {
  position: relative;
  width: min(1740px, calc(100vw - 48px));
  height: min(96vh, calc(100svh - 32px));
  max-height: 1120px;
  min-height: 520px;
  display: flex;
  flex-direction: column;
  padding: 0 32px;
  border: 1px solid var(--line);
  box-shadow: 0 16px 60px rgba(0, 0, 0, 0.65);
  background: rgba(9, 11, 10, .96);
}
.topbar { min-height: 72px; flex: 0 0 auto; }
.wordmark { padding: 0; border: 0; background: transparent; cursor: pointer; }
.system-status { margin-left: auto; white-space: nowrap; }
.status-divider { color: var(--green-dim); }
.site-nav { margin-left: 8px; gap: 17px; }
.site-nav button { padding: 8px 0; border: 0; background: transparent; color: #aeb5ad; cursor: pointer; font: 10px var(--mono); transition: color .2s ease; }
.site-nav button:hover, .site-nav button[aria-current="page"] { color: var(--green); }
.site-nav button[aria-current="page"]::after { display: block; height: 1px; margin-top: 5px; background: var(--green); content: ""; }
#stage { position: relative; flex: 1 1 auto; min-height: 0; overflow: hidden; border: 1px solid var(--line); background: rgba(9, 11, 10, .88); }
.screen { position: absolute; inset: 0; display: none; overflow-y: auto; overscroll-behavior: contain; padding: clamp(24px, 4vw, 54px); scrollbar-color: var(--green-dim) transparent; scrollbar-width: thin; }
.screen.is-active {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: stretch;
  gap: 22px;
  animation: screen-enter .24s ease both;
}
.screen::-webkit-scrollbar { width: 6px; }
.screen::-webkit-scrollbar-thumb { background: var(--green-dim); }
@keyframes screen-enter { from { opacity: .3; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.home-screen.is-active { display: grid; grid-template-columns: minmax(0, 1fr) 210px; align-items: center; gap: 36px; }
.home-content { max-width: 820px; }
.hero-topline { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-bottom: 48px; color: var(--muted); font-size: 9px; }
.hero-topline span:first-child { color: var(--green); }
.home-screen .eyebrow { margin-bottom: 12px; }
.home-screen h1 { margin: 0 0 13px; font-size: clamp(58px, 9vw, 108px); }
.hero-role { margin: 17px 0 14px; color: var(--green); font-size: 13px; }
.hero-role span { color: var(--muted); }
.hero-rule { width: min(100%, 570px); height: 1px; background: var(--line); }
.intro { max-width: 700px; margin: 19px 0 25px; color: #bbc1ba; font-size: 13px; line-height: 1.85; }
.prompt-mark { margin-right: 7px; color: var(--green); }
.home-menu { display: grid; width: min(100%, 700px); border-top: 1px solid var(--line); }
.menu-item { min-height: 45px; display: grid; grid-template-columns: 48px 1fr 24px; align-items: center; gap: 10px; padding: 0 12px; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: #d1d6d0; cursor: pointer; text-align: left; font: 500 12px var(--mono); transition: background .18s ease, color .18s ease; }
.menu-item.is-selected { background: rgba(157, 242, 173, .07); color: var(--green); }
.menu-index { color: var(--green-dim); font-size: 10px; }
.menu-arrow { justify-self: end; color: var(--green); font-size: 16px; }
.home-readout { align-self: end; margin-bottom: 4px; padding: 0 0 6px 18px; border-left: 1px solid var(--line); }
.readout-label { color: var(--muted); font-size: 9px; letter-spacing: .04em; }
.home-readout strong { display: block; margin: 13px 0 35px; font: 500 24px/1.3 var(--display); }
.home-readout strong span { color: var(--green); }
.aside-coordinate { display: flex; flex-direction: column; gap: 5px; margin-top: 16px; padding-top: 11px; border-top: 1px solid var(--line); }
.aside-coordinate span:first-child { color: var(--muted); font-size: 9px; }
.aside-coordinate span:last-child { color: var(--cyan); font-size: 9px; }
.page-controls { min-height: 60px; display: flex; flex: 0 0 auto; align-items: center; gap: 22px; border-top: 1px solid var(--line); }
.pager-button { display: inline-flex; align-items: center; gap: 8px; padding: 8px 0; border: 0; background: transparent; color: var(--green); cursor: pointer; font: 10px var(--mono); }
.pager-button:disabled { opacity: .35; }
.page-progress { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 9px; }
#page-dots { display: flex; gap: 5px; }
#page-dots button { width: 15px; height: 3px; padding: 0; border: 0; background: var(--line); cursor: pointer; }
#page-dots button.is-active { background: var(--green); }
.keyboard-hint { display: flex; align-items: center; gap: 5px; margin-left: auto; color: var(--muted); font-size: 8px; }
.keyboard-hint kbd { min-width: 18px; padding: 3px 4px; border: 1px solid var(--line); color: var(--paper); font: 8px var(--mono); text-align: center; }
.hint-divider { padding: 0 4px; color: var(--green-dim); }
.screen-heading { margin-bottom: 28px; }
.screen-heading .eyebrow { margin-bottom: 10px; }
.screen-heading h2 { margin-bottom: 6px; font-size: clamp(32px, 5vw, 52px); }
.screen-heading h2 span { color: var(--green); }
.section-note { margin: 9px 0 0; color: var(--muted); font-size: 11px; }
.about-layout { display: grid; grid-template-columns: minmax(180px, .62fr) minmax(0, 1.38fr); gap: clamp(22px, 4vw, 54px); align-items: start; }
.profile-photo { position: sticky; top: 0; margin: 0; padding: 10px; border: 1px solid var(--line); background: var(--panel-raised); }
.profile-photo img { display: block; width: 100%; max-height: 390px; aspect-ratio: 4 / 5; object-fit: cover; object-position: center 30%; filter: saturate(.78); }
.profile-photo figcaption { padding: 11px 2px 2px; color: var(--muted); font-size: 9px; }
.profile-photo figcaption span { color: var(--green); }
.about-copy { color: #b9c0b8; font-size: 12px; line-height: 1.85; }
.about-copy p { margin: 0 0 16px; }
.about-copy .quote { padding: 13px 15px; border-left: 2px solid var(--green); background: var(--panel-raised); color: var(--paper); font-size: 11px; }
.quote span { display: block; margin-top: 7px; color: var(--green); font-size: 9px; }
.cv-link { display: inline-flex; align-items: center; gap: 10px; margin-top: 8px; padding: 11px 14px; border: 1px solid var(--green-dim); color: var(--green); font-size: 10px; transition: background .2s ease; }
.cv-link.is-option-selected { background: rgba(157, 242, 173, .08); }
.file-type { color: var(--muted); font-size: 8px; }
.skills-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px 34px; }
.skill-group { min-width: 0; padding: 17px 0; border-top: 1px solid var(--line); }
.skill-group h3 { margin: 0 0 15px; color: var(--green); font: 500 14px var(--display); }
.skill-row { display: grid; grid-template-columns: minmax(110px, 1fr) minmax(65px, 1.5fr) 34px; align-items: center; gap: 10px; margin: 10px 0; }
.skill-name { overflow: hidden; color: #c0c6bf; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.skill-bar { height: 5px; overflow: hidden; background: #202621; }
.skill-fill { display: block; width: var(--skill-level); height: 100%; background: var(--green-dim); animation: skill-fill-in .7s ease both; }
.skill-value { color: var(--muted); font-size: 8px; text-align: right; }
@keyframes skill-fill-in { from { width: 0; } to { width: var(--skill-level); } }
.experience-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 34px; }
.grid-label { display: flex; align-items: center; gap: 9px; margin: 0 0 13px; color: var(--paper); font: 500 12px var(--mono); }
.grid-label span { width: 15px; height: 1px; background: var(--green); }
.card-list { display: grid; gap: 11px; }
.experience-card, .project-card { display: block; min-width: 0; padding: 16px; border: 1px solid var(--line); border-left: 2px solid var(--green-dim); background: rgba(17, 21, 18, .76); color: var(--paper); }
a.project-card { transition: border-color .18s ease, background .18s ease; }
a.project-card:hover { border-color: var(--green); background: rgba(157, 242, 173, .05); }
.card-tag { color: var(--cyan); font-size: 8px; }
.experience-card h4, .project-card h4 { margin: 10px 0 7px; font: 500 16px var(--display); }
.experience-card p, .project-card p { margin: 0; color: #aeb5ad; font-size: 10px; line-height: 1.7; }
.card-meta { display: block; margin-top: 13px; color: var(--green-dim); font-size: 8px; }
.projects-block { margin-top: 28px; }
.project-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.project-card { position: relative; min-height: 170px; padding-bottom: 45px; }
.project-card h4 { font-size: 18px; }
.project-card .card-meta { margin-top: 11px; }
.project-card .card-cta { position: absolute; right: 15px; bottom: 14px; color: var(--green); font-size: 8px; }
@media (max-width: 760px) {
  .page-shell { width: calc(100% - 28px); min-height: 520px; }
  .topbar { min-height: 90px; flex-wrap: wrap; gap: 0 12px; padding: 10px 0 7px; }
  .wordmark { font-size: 11px; }
  .system-status { margin-left: auto; font-size: 8px; }
  .site-nav { position: static; order: 3; display: flex; width: 100%; justify-content: space-between; gap: 5px; margin: 6px 0 0; }
  .site-nav button { font-size: 8px; }
  #stage { min-height: 0; }
  .screen { padding: 23px 18px; }
  .home-screen.is-active { grid-template-columns: minmax(0, 1fr); align-content: center; gap: 0; }
  .home-readout { display: none; }
  .hero-topline { gap: 7px 12px; margin-bottom: 26px; font-size: 7px; }
  .home-screen h1 { font-size: clamp(52px, 13vw, 78px); }
  .hero-role { font-size: 10px; }
  .intro { max-width: 520px; font-size: 11px; }
  .menu-item { min-height: 41px; font-size: 10px; }
  .page-controls { min-height: 53px; gap: 13px; }
  .pager-button { gap: 4px; font-size: 8px; }
  .page-progress { gap: 7px; font-size: 8px; }
  #page-dots { gap: 3px; }
  #page-dots button { width: 10px; }
  .keyboard-hint { display: flex; gap: 3px; font-size: 7px; }
  .keyboard-hint kbd { min-width: 18px; }
  .hint-divider { display: none; }
  .about-layout { grid-template-columns: 130px minmax(0, 1fr); gap: 17px; }
  .profile-photo { padding: 6px; }
  .profile-photo img { max-height: 210px; }
  .profile-photo figcaption { font-size: 7px; }
  .about-copy { font-size: 10px; line-height: 1.7; }
  .about-copy p { margin-bottom: 11px; }
  .about-copy .quote { padding: 10px; font-size: 9px; }
  .skills-grid { gap: 12px 22px; }
  .skill-row { grid-template-columns: minmax(85px, 1fr) minmax(35px, 1fr) 29px; gap: 6px; }
  .skill-name { font-size: 8px; }
  .experience-columns { gap: 16px; }
  .experience-card, .project-card { padding: 12px; }
  .experience-card h4, .project-card h4 { font-size: 13px; }
  .experience-card p, .project-card p { font-size: 9px; }
  .project-card { min-height: 180px; }
}
@media (max-width: 460px) {
  .page-shell { width: calc(100% - 20px); }
  .topbar { min-height: 86px; }
  .status-divider { display: none; }
  .site-nav button { font-size: 7px; }
  .screen { padding: 19px 13px; }
  .home-screen.is-active { align-content: center; }
  .hero-topline { margin-bottom: 20px; font-size: 6px; }
  .home-screen h1 { font-size: clamp(45px, 12vw, 58px); }
  .intro { font-size: 10px; }
  .menu-item { grid-template-columns: 37px 1fr 18px; gap: 7px; min-height: 38px; padding: 0 8px; font-size: 9px; }
  .page-controls { gap: 8px; }
  .page-progress { gap: 5px; }
  #page-dots button { width: 7px; }
  .pager-button span { display: none; }
  .about-layout { grid-template-columns: 1fr; }
  .profile-photo { position: relative; width: min(170px, 55%); }
  .profile-photo img { max-height: 185px; }
  .skills-grid { grid-template-columns: 1fr; gap: 0; }
  .skill-group { padding: 12px 0; }
  .experience-columns { grid-template-columns: 1fr; gap: 20px; }
  .project-grid { grid-template-columns: 1fr; }
  .project-card { min-height: 145px; }
  .keyboard-hint { display: flex; gap: 3px; font-size: 6px; white-space: nowrap; }
}
@media (prefers-reduced-motion: reduce) {
  .screen.is-active { animation: none; }
  .skill-fill { animation: none; }
}
.wordmark { text-decoration: none; }
.route-bar { display: flex; align-items: center; gap: 9px; margin-left: auto; color: var(--green); font-size: 10px; white-space: nowrap; }
.route-prompt { color: var(--muted); }
.route-bar a { color: var(--green); }
.route-bar a:hover { text-decoration: none; }
#route-page { color: var(--cyan); }
.home-screen.is-active { grid-template-columns: minmax(0, 1.15fr) minmax(270px, .85fr); gap: clamp(28px, 5vw, 72px); overflow: hidden; }
.home-content { min-width: 0; }
.home-directory { align-self: center; min-width: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; perspective: 760px; perspective-origin: center bottom; }
.directory-heading { grid-column: 1 / -1; min-height: 34px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.directory-heading > span:last-child { color: var(--green-dim); font-size: 8px; }
.menu-item.folder-tile { position: relative; min-height: 112px; display: grid; grid-template-columns: minmax(0, 1fr) 18px; grid-template-rows: 1fr auto auto; align-items: end; gap: 5px 8px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); text-decoration: none; perspective: 600px; transform-style: flat; transition: transform .28s ease, border-color .18s ease, background-color .18s ease, color .18s ease; }
.menu-item.folder-tile .folder-back::before { position: absolute; top: -9px; left: -1px; width: 38%; height: 9px; border: 1px solid var(--green-dim); border-bottom: 0; border-radius: 5px 5px 0 0; background: var(--green-dim); content: ""; }
.menu-item.folder-tile:hover { z-index: 2; border-color: var(--ink); background: transparent; color: var(--ink); }
.menu-item.folder-tile:focus-visible { outline: 0; }
.menu-item.folder-tile > * { position: relative; z-index: 5; }
.menu-item.folder-tile > .menu-index, .menu-item.folder-tile > .folder-name, .menu-item.folder-tile > .folder-meta, .menu-item.folder-tile > .menu-arrow { position: relative; z-index: 5; }
.menu-item.folder-tile .folder-back { position: absolute; z-index: 1; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 1px solid var(--green-dim); border-radius: 0 8px 8px 8px; background: var(--green-dim); }
.menu-item.folder-tile .folder-file { position: absolute; z-index: 2; bottom: 10px; left: 15px; width: calc(100% - 30px); height: 68%; border: 1px solid var(--line); border-radius: 4px; background: var(--paper); box-shadow: 0 2px 5px rgba(0, 0, 0, .14); opacity: 1; transition: transform .3s ease-out; }
.menu-item.folder-tile .folder-file-1 { transform: translateY(0); }
.menu-item.folder-tile .folder-file-2 { transform: translate(5px, -5px) rotate(2deg); }
.menu-item.folder-tile .folder-front { position: absolute; z-index: 4; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 2px solid var(--ink); border-radius: 0 8px 8px 8px; background: var(--green); box-shadow: 0 4px 10px rgba(0, 0, 0, .22); transform: rotateX(0); transform-origin: bottom center; backface-visibility: visible; transition: transform .3s ease-out, background-color .3s ease-out; }
.menu-item.folder-tile:hover .folder-front { transform: rotateX(-40deg); background: color-mix(in srgb, var(--green) 78%, var(--ink)); }
.menu-item.folder-tile:hover .folder-file-1 { transform: translateY(-20px); }
.menu-item.folder-tile:hover .folder-file-2 { transform: translateY(-25px) translate(5px, -5px) rotate(4deg); }
.menu-index { grid-column: 2; grid-row: 1; justify-self: end; color: var(--green); font-size: 8px; }
.folder-name { grid-column: 1; grid-row: 2; color: inherit; font-size: 12px; }
.folder-meta { grid-column: 1; grid-row: 3; color: var(--green-dim); font-size: 7px; }
.menu-item.folder-tile .menu-arrow { grid-column: 3; grid-row: 2 / 4; align-self: center; justify-self: end; }
.menu-item.folder-tile .menu-arrow { grid-column: 2; }
.menu-item.folder-tile > .menu-index, .menu-item.folder-tile > .folder-name, .menu-item.folder-tile > .folder-meta, .menu-item.folder-tile > .menu-arrow { color: var(--ink); opacity: 1; transition: opacity .3s ease-out; }
.menu-item.folder-tile:hover > .menu-index, .menu-item.folder-tile:hover > .folder-name, .menu-item.folder-tile:hover > .folder-meta, .menu-item.folder-tile:hover > .menu-arrow { opacity: 0; }
.menu-item.folder-tile.is-selected::before, .menu-item.folder-tile.is-option-selected::before { border-color: var(--ink); background: var(--green); }
.menu-item.folder-tile.is-selected .menu-index, .menu-item.folder-tile.is-option-selected .menu-index,
.menu-item.folder-tile.is-selected .folder-meta, .menu-item.folder-tile.is-option-selected .folder-meta,
.menu-item.folder-tile.is-selected .menu-arrow, .menu-item.folder-tile.is-option-selected .menu-arrow { color: var(--ink); }
.directory-hint { grid-column: 1 / -1; margin: 6px 0 0; color: var(--muted); font-size: 8px; }
.directory-hint kbd { display: inline-block; margin-right: 3px; padding: 3px 5px; border: 1px solid var(--line); color: var(--paper); font: 8px var(--mono); }
.directory-hint kbd:nth-of-type(2) { margin-right: 8px; }
.home-screen .hero-topline { margin-bottom: 31px; }
.home-screen h1 { font-size: clamp(53px, 7vw, 88px); }
.home-screen .intro { font-size: 12px; }
.page-controls { gap: 18px; }
.page-progress { gap: 8px; }
.option-label { color: var(--green-dim); font-size: 8px; }
.keyboard-hint { font-size: 8px; }
.is-option-selected:not(.menu-item) { outline: 1px solid var(--green-dim); outline-offset: 3px; }
.skill-group.is-option-selected { outline-offset: 5px; }
.experience-card.is-option-selected, .project-card.is-option-selected { border-color: var(--green); }
.contact-chip.is-option-selected, .cv-link.is-option-selected { outline-offset: 3px; }
.route-bar, .route-bar a, #route-page { color: var(--green); }
.route-bar { gap: 4px; }
.page-controls { justify-content: space-between; }
.keyboard-hint { margin-left: 0; }
.control-pickers { display: flex; align-items: center; gap: 8px; }
@media (max-width: 760px) {
  .topbar { min-height: 91px; }
  .route-bar { order: 3; width: 100%; margin: 7px 0 0; font-size: 9px; }
  .home-screen.is-active { grid-template-columns: minmax(0, 1fr); align-content: start; gap: 25px; overflow: hidden; }
  .home-screen .hero-topline { margin-bottom: 20px; }
  .home-screen h1 { font-size: clamp(48px, 11vw, 68px); }
  .home-screen .intro { margin-bottom: 0; }
  .home-directory { width: 100%; }
  .menu-item.folder-tile { min-height: 86px; padding: 9px; }
  .directory-hint { margin-top: 10px; }
  .page-controls { gap: 12px; }
  .keyboard-hint { gap: 4px; font-size: 7px; }
  .keyboard-hint kbd { min-width: 17px; }
  .keyboard-hint .hint-divider { display: none; }
}
@media (max-width: 460px) {
  .route-bar { gap: 6px; font-size: 8px; }
  .home-screen.is-active { gap: 17px; }
  .home-screen .hero-topline { gap: 6px 10px; margin-bottom: 16px; font-size: 6px; }
  .home-screen h1 { font-size: clamp(43px, 11vw, 54px); }
  .menu-item { min-height: 39px; padding: 0 8px; font-size: 9px; }
  .page-controls { gap: 8px; }
  .keyboard-hint { gap: 3px; flex: 1; justify-content: flex-start; font-size: 6px; white-space: nowrap; }
  .keyboard-hint .hint-divider { display: none; }
}
@media (max-height: 700px) {
  .home-screen.is-active { gap: 12px; padding: 12px 14px; }
  .home-screen .hero-topline { margin-bottom: 8px; }
  .home-screen .eyebrow { margin-bottom: 6px; }
  .home-screen h1 { font-size: clamp(38px, 6vh, 52px); }
  .home-screen .hero-role { margin: 7px 0; }
  .home-screen .intro { margin: 8px 0 0; font-size: 9px; line-height: 1.35; }
  .menu-item.folder-tile { min-height: 60px; grid-template-columns: 23px minmax(0, 1fr) 14px; gap: 3px 6px; padding: 6px; }
  .menu-item.folder-tile .folder-icon { width: 19px; height: 13px; }
  .menu-item.folder-tile .folder-icon::before { top: -4px; width: 7px; height: 3px; }
  .folder-name { font-size: 9px; }
  .folder-meta { font-size: 6px; }
  .directory-heading { min-height: 24px; }
  .directory-hint { margin-top: 3px; font-size: 7px; }
}
@media (max-height: 560px) {
  .page-shell { min-height: 0; }
  .topbar { min-height: 68px; padding-top: 6px; padding-bottom: 3px; }
  .route-bar { order: 0; width: auto; margin: 0 0 0 auto; font-size: 7px; }
  .system-status { font-size: 7px; }
  .page-controls { min-height: 42px; }
  .home-screen.is-active { gap: 8px; }
  .menu-item.folder-tile { min-height: 50px; }
  .directory-heading { min-height: 21px; }
  .directory-hint { margin-top: 1px; }
}
@media (min-width: 761px) and (max-height: 760px) {
  #screen-about { padding-block: 24px; }
}
@media (min-width: 1300px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 48px; }
  .home-content { max-width: 1100px; }
  .intro { max-width: 880px; }
  .hero-rule, .home-menu { width: min(100%, 880px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
  .skills-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}
@media (min-width: 1700px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 64px; }
  .home-content { max-width: 1300px; }
  .intro { max-width: 1020px; }
  .hero-rule, .home-menu { width: min(100%, 1020px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}

after.content:
:root {
  color-scheme: dark;
  --ink: #090b0a;
  --panel: #0d100e;
  --panel-raised: #111512;
  --line: #2b322d;
  --muted: #858c85;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
  --cyan: #91f3a8;
  --grid-line: rgba(32, 239, 79, .025);
  --orb-core: #010602;
  --orb-glow: #20ef4f;
  --mono: "DM Mono", "Courier New", monospace;
  --display: "Space Grotesk", "Trebuchet MS", sans-serif;
  font-family: var(--mono);
  background: var(--ink);
  color: var(--paper);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 32px; }
body {
  min-width: 320px;
  margin: 0;
  background-color: var(--ink);
  background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  color: var(--paper);
}
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--green); outline-offset: 4px; }
.is-option-selected:focus-visible { outline: 0; }
.page-shell { width: min(1120px, calc(100% - 64px)); margin: 0 auto; }
.topbar { min-height: 76px; display: flex; align-items: center; gap: 30px; border-bottom: 1px solid var(--line); }
.wordmark { display: inline-flex; align-items: center; gap: 10px; color: var(--paper); font: 600 13px var(--mono); letter-spacing: 0; white-space: nowrap; }
.wordmark-mark { color: var(--green); font: 700 19px var(--display); }
.wordmark-mark span { color: var(--paper); }
.wordmark-muted { color: var(--muted); }
.system-status { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 10px; }
.status-light { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px rgba(157, 242, 173, .7); }
.site-nav { display: flex; gap: 25px; margin-left: auto; }
.site-nav a { color: #bdc3bc; font-size: 11px; transition: color .2s ease; }
.site-nav a:hover { color: var(--green); }
.site-nav a span { margin-left: 4px; color: var(--green-dim); font-size: 9px; }
.menu-toggle { display: none; }
.terminal-frame { border: 1px solid var(--line); background: rgba(9, 11, 10, .92); }
.hero { position: relative; margin-top: 28px; padding: 20px 30px 0; overflow: hidden; }
.hero::before { position: absolute; top: 0; left: 0; width: 3px; height: 88px; background: var(--green); content: ""; }
.hero-topline { display: flex; flex-wrap: wrap; gap: 8px 26px; color: var(--muted); font-size: 11px; }
.hero-topline span:first-child { color: var(--green); }
.hero-main { display: grid; grid-template-columns: minmax(0, 1fr) 220px; gap: 32px; align-items: center; padding: 64px 0 52px; }
.eyebrow { margin: 0 0 18px; color: var(--muted); font-size: 11px; letter-spacing: .08em; }
.eyebrow span { color: var(--green-dim); }
